//===----------------------------------------------------------------------===//
//
// This file defines the Wony-specific support for the FastISel class. Some
// of the target-specific code is generated by tablegen in the file
// WonyGenFastISel.inc, which is #included here.
//
//===----------------------------------------------------------------------===//

#include "Wony.h" // For the declaration of Wony::createFastISel.
#include "WonyInstrInfo.h"
#include "WonyRegisterInfo.h" // For the register classes.
#include "WonyCallingConvention.h"

#include "llvm/CodeGen/FastISel.h"
#include "llvm/CodeGen/FunctionLoweringInfo.h"

using namespace llvm;

namespace {

class WonyFastISel final : public FastISel {
private:
  // Selection routines.
  bool selectRet(const Instruction &I);

public:
  // Backend specific FastISel code.
  explicit WonyFastISel(FunctionLoweringInfo &FuncInfo,
                        const TargetLibraryInfo *LibInfo)
      : FastISel(FuncInfo, LibInfo, /*SkipTargetIndependentISel=*/true) {}

  bool fastSelectInstruction(const Instruction *I) override;

#include "WonyGenFastISel.inc"
};

} // end anonymous namespace

bool WonyFastISel::fastSelectInstruction(const Instruction *I) {
  // Skip FastISel is we've been told so.
  if (TLI.fallBackToDAGISel(*I)) {
    return false;
  }

  switch (I->getOpcode()) {
    case Instruction::Ret:
      return selectRet(*I);
    default:
      break;
  }

  // fall-back to target-independent instruction selection.
  // If we don't have a specific selection routine for this instruction,
  return selectOperator(I, I->getOpcode());
}

FastISel *Wony::createFastISel(FunctionLoweringInfo &FuncInfo,
                                const TargetLibraryInfo *LibInfo) {

  return new WonyFastISel(FuncInfo, LibInfo);
}

bool WonyFastISel::selectRet(const Instruction &I) {
  if (!FuncInfo.CanLowerReturn)
    return false;

  const Function &F = *I.getParent()->getParent();

  // Give up on anything fancy.
  if (F.isVarArg()) {
    return false;
  }
  if (TLI.supportSplitCSR(FuncInfo.MF)) {
    return false;
  }

  const ReturnInst &Ret = cast<ReturnInst>(I);
  if (Ret.getNumOperands() > 0) {
    return false;
  }

  BuildMI(*FuncInfo.MBB, FuncInfo.InsertPt, MIMD, TII.get(Wony::RETURN));
  return true;
}
